inline const APM *GetAPM(const void *buf) {
  return ::flatbuffers::GetRoot<APM>(buf);
}

inline const APM *GetSizePrefixedAPM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<APM>(buf);
}

inline const char *APMIdentifier() {
  return "$APM";
}

inline bool APMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, APMIdentifier());
}

inline bool SizePrefixedAPMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, APMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyAPMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<APM>(APMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedAPMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<APM>(APMIdentifier());
}

inline void FinishAPMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<APM> root) {
  fbb.Finish(root, APMIdentifier());
}

inline void FinishSizePrefixedAPMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<APM> root) {
  fbb.FinishSizePrefixed(root, APMIdentifier());
}

